1	/**
2	 * Scheduling priority for the 44 consonants (Task 4.1).
3	 *
4	 * CONTEXT.md rule 2 — build on, never beside. `ThaiConsonant.priority` (and
5	 * the field on the other symbol subclasses) already exists at 98 sites; this
6	 * module is the field's first consumer, not a second priority concept. There
7	 * is exactly one place the optional numeric priority field is declared, in
8	 * `symbols.ts` — asserted by `lessonSequence.test.ts`'s
9	 * "declares symbol priority exactly once" case and re-asserted here against
10	 * the derivation this module owns.
11	 *
12	 * Demotion changes what a letter's `priority` number IS, computed from
13	 * corpus frequency, never whether the letter is in the set: the count of
14	 * consonants is unaffected (AC6).
15	 */
16	
17	import vocabularyData from "../../vocabulary/data/vocabulary.json";
18	import { consonants } from "./symbols";
19	
20	interface CorpusEntry {
21		readonly characters?: readonly string[];
22	}
23	
24	const CONSONANT_CHARACTERS: readonly string[] = consonants.map(
25		(consonant) => consonant.character,
26	);
27	
28	/**
29	 * Any-position occurrence count across the vocabulary corpus: every
30	 * character slot in every entry's `characters` array, not just word-initial
31	 * position (AC5). An initial-position count would demote letters that are
32	 * common medially or finally but rare as an initial — measured, seven of the
33	 * ten letters this phase demotes still appear in the corpus's top-600 words.
34	 */
35	export function computeAnyPositionFrequency(
36		entries: readonly CorpusEntry[] = vocabularyData as CorpusEntry[],
37	): Map<string, number> {
38		const counts = new Map<string, number>(
39			CONSONANT_CHARACTERS.map((character) => [character, 0]),
40		);
41		for (const entry of entries) {
42			for (const character of entry.characters ?? []) {
43				if (counts.has(character)) {
44					counts.set(character, (counts.get(character) ?? 0) + 1);
45				}
46			}
47		}
48		return counts;
49	}
50	
51	/**
52	 * Rank order derived from corpus frequency: rank 1 is the most frequent
53	 * consonant, rank 44 the rarest. Ties break on the character itself (plain
54	 * code-point order) so the derivation is deterministic and reproducible from
55	 * the corpus alone — never hand-curated.
56	 */
57	export function deriveConsonantPriority(
58		frequency: Map<string, number> = computeAnyPositionFrequency(),
59	): Map<string, number> {
60		const ranked = [...CONSONANT_CHARACTERS].sort((a, b) => {
61			const byFrequency = (frequency.get(b) ?? 0) - (frequency.get(a) ?? 0);
62			if (byFrequency !== 0) return byFrequency;
63			return a < b ? -1 : a > b ? 1 : 0;
64		});
65		return new Map(ranked.map((character, index) => [character, index + 1]));
66	}
67	
68	/**
69	 * The scheduling priority for a consonant — reads `ThaiConsonant.priority`
70	 * directly, the single declaration site. Rare letters get a larger number
71	 * (lower priority) without leaving the symbol set.
72	 */
73	export function getSchedulingPriority(character: string): number | undefined {
74		return consonants.find((consonant) => consonant.character === character)
75			?.priority;
76	}
77	
78	/** The number of consonants in the SRS. Demotion must never change this. */
79	export function consonantCount(): number {
80		return consonants.length;
